+// predicates controlling emit of s{b|h|w|d}.{rl,aqrl} and associated membars
+
+bool needs_releasing_store(const Node *n) {
+  if (!UseZalasr) return false;
+  assert(n->is_Store(), "expecting a store");
+  return n->as_Store()->trailing_membar() != nullptr;
+}
